"""The Hoard / Dragon's Forge art (your painted forge sheet): background, name sign, label, price plaque, upgrade icons, ingots, star medal.
img(name) gives the surface; scaled(name, w, h) a cached resized copy."""
import base64
import io
import pygame

# spots in forge_bg.jpg, in its own pixels
LIGHTS = ((540, 40, 48), (1310, 40, 48), (235, 368, 30), (90, 578, 30), (1622, 348, 30))   # torches and lanterns (x, y, radius)
COALS = (935, 430, 200)                                    # the forge's coal bed (x, y, half-width)
ANVILS = ((500, 498), (935, 498), (1370, 498))             # top middle of each anvil (Thick Scales, Deep Lungs, Coin Magnet)
PEDESTAL_Y = 676                                           # middle of the stone pedestal fronts (price plaques)
PNG = {
  'forge_bg': ('jpg', ''),
  'forge_label': ('png', ''),
  'forge_sign': ('png', ''),
  'icon_upg_coin_magnet': ('png', ''),
  'icon_upg_deep_lungs': ('png', ''),
  'icon_upg_thick_scales': ('png', ''),
  'ingot_off': ('png', ''),
  'ingot_on': ('png', ''),
  'price_plaque': ('png', ''),
  'star_medal': ('png', ''),
}
_C = {}


def has(name):
  return name in PNG


def img(name):
  s = _C.get(name)
  if s is None:
    ext, data = PNG[name]
    s = pygame.image.load(io.BytesIO(base64.b64decode(data)), 'art.' + ext)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def scaled(name, w, h, smooth=True):
  k = (name, int(w), int(h))
  s = _C.get(k)
  if s is None:
    src = img(name)
    fn = getattr(pygame.transform, 'smoothscale', None) if smooth else None
    try:
      s = (fn or pygame.transform.scale)(src, (max(1, int(w)), max(1, int(h))))
    except Exception:
      s = pygame.transform.scale(src, (max(1, int(w)), max(1, int(h))))
    _C[k] = s
  return s
